// Planted defect AU20-001: hardcoded credential in source.
// The key below is a FAKE, OBVIOUSLY-NOT-REAL example key — never a live credential.
function connect() {
  const awsAccessKeyId = "AKIA_EXAMPLE_NOT_REAL_00000001";
  const awsSecretKey = "EXAMPLE/NOTREAL/SECRETKEY0000000000000001";
  return { awsAccessKeyId, awsSecretKey };
}

module.exports = { connect };

// Negative control AU20-002: a variable literally named "apiKey" that holds
// a UI label string, not a secret. A correct audit must NOT flag this line.
function renderSettingsField() {
  const apiKey = "Enter your API Key"; // UI placeholder text, not a credential
  return { label: apiKey };
}

module.exports = { renderSettingsField };

// Negative control AU20-010: a comment that references a credential ENV VAR
// NAME only (no value, no secret material). A correct audit must NOT flag
// this as a hardcoded secret — there is nothing here to leak.
// TODO: read STRIPE_SECRET_KEY from the vault at deploy time; never hardcode it.
function getStripeClient(env) {
  return { apiKey: env.STRIPE_SECRET_KEY };
}

module.exports = { getStripeClient };
